import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

type ReviewQueueEntry = { vendor_id: string; vendor_name: string; extractions: Extraction[] };

test(
  "an admin approves a vendor's w9 extraction and the vendor is listed in the review queue",
  { tag: "@LIF-12" },
  async ({ apiAs }) => {
    // Arrange: an admin creates a vendor, uploads three documents, and submits it for review.
    const admin = await apiAs("admin");
    const suffix = crypto.randomUUID();

    const vendor = await expectStatus<Vendor>(
      await admin.post("/api/vendors", {
        data: {
          name: `LIF-12 Vendor ${suffix}`,
          category: "software",
          contact_email: `lif12-${suffix}@example.test`,
        },
      }),
      201,
    );

    for (const kind of ["w9", "insurance_certificate", "contract"] as const) {
      await expectStatus<Document>(
        await admin.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 lif-12 test") },
          },
        }),
        201,
      );
    }

    await expectStatus<Vendor>(await admin.post(`/api/vendors/${vendor.id}/submit`), 200);

    const documents = await expectStatus<Document[]>(await admin.get(`/api/vendors/${vendor.id}/documents`), 200);
    const w9 = documents.find((d) => d.kind === "w9");
    expect(w9, "vendor should have a w9 document").toBeDefined();

    // Extraction runs asynchronously after upload, so wait for the w9 extraction to be pending review.
    let w9Extraction: Extraction | undefined;
    await expect
      .poll(
        async () => {
          const response = await admin.get(`/api/documents/${w9!.id}/extraction`);
          if (response.status() !== 200) return null;
          w9Extraction = (await response.json()) as Extraction;
          return w9Extraction.status;
        },
        { timeout: 60_000 },
      )
      .toBe("pending_review");

    // Act: approve the w9 extraction.
    const decided = await expectStatus<Extraction>(
      await admin.post(`/api/extractions/${w9Extraction!.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );

    // Assert: the decision is recorded, and the review queue still lists the vendor.
    expect(decided.status).toBe("approved");

    const queue = await expectStatus<ReviewQueueEntry[]>(await admin.get("/api/review-queue"), 200);
    expect(queue.map((entry) => entry.vendor_id)).toContain(vendor.id);
  },
);
